import type { NextRequest } from "next/server";
import { authProxy } from "@/lib/sb/proxy";

/**
 * Every request but static assets, through each slice's step in turn: the
 * i18n slice maps a language URL (`/hu/store`) onto the page it renders, then
 * the auth slice rate-limits and refreshes the Supabase session for that
 * page. A composition without one of them has its step unwired here.
 */
export async function proxy(request: NextRequest) {
  return authProxy(request);
}

export const config = {
  // Everything that can touch auth — API routes included — but not static
  // assets. Refreshing the session in exactly one layer (here) keeps
  // Supabase's single-use refresh-token rotation from being lost.
  matcher: [
    "/((?!_next/static|_next/image|favicon.ico|trademarks|images|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico|mp4)$).*)",
  ],
};

// Content barrel. Each line belongs to a surface: the scaffolder removes the
// lines for surfaces a composition leaves out (see composition/surfaces/*.json).
export * from "./misc/kbar";

import { headers } from "next/headers";
import { LOCALE_HEADER, defaultLocale, locales, matchLocale } from "./index";

/**
 * The locale this request renders in. One language: the default, read without
 * touching the request, so pages stay static. Several: the one the i18n
 * slice's proxy took from the URL (`/hu/store`), which makes rendering
 * per-request.
 */
export async function getLocale(): Promise<string> {
  if (locales.length < 2) return defaultLocale;
  return matchLocale((await headers()).get(LOCALE_HEADER)) ?? defaultLocale;
}

"use client";

import { createContext, useContext } from "react";
import { defaultLocale } from "@/lib/i18n";

const LocaleContext = createContext(defaultLocale);

/** Hands the request's locale, resolved by the root layout, to client components. */
export function LocaleProvider({
  locale,
  children,
}: { locale: string; children: React.ReactNode }) {
  return <LocaleContext.Provider value={locale}>{children}</LocaleContext.Provider>;
}

/** The locale the page renders in. Server components call `getLocale()` instead. */
export function useLocale(): string {
  return useContext(LocaleContext);
}

