Now `custom.css`: the font variables and the 4px corner radius, applied through the design system's radius tokens so buttons, inputs, cards and menus all follow.

```css src/resources/custom.css
:root {
  --default-border: var(--neutral-alpha-weak);

  /* Fonts: system stacks, so nothing is downloaded. The design system reads
     these four variables for heading, body, label and code text. */
  --font-heading: Georgia, "Times New Roman", serif;
  --font-body: ui-sans-serif, system-ui, sans-serif;
  --font-label: ui-sans-serif, system-ui, sans-serif;
  --font-code: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

/* Brand corner radius: 4px on buttons, inputs, cards and menus.
   The design system draws every corner from these radius tokens, so setting
   them on the root (and on each border style, which would otherwise redefine
   them) applies the radius to all components at once. */
:root,
[data-border="rounded"],
[data-border="playful"],
[data-border="conservative"],
[data-border="sharp"] {
  --radius-xs: 2px;
  --radius-s: 4px;
  --radius-m: 4px;
  --radius-l: 4px;
  --radius-xl: 4px;
  --radius-full: 4px;
}

/* Headings and display text use the serif face; make sure the weight stays
   readable in a system serif. */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-family: var(--font-heading);
}

/* Visible focus ring in the brand colour. */
:focus-visible {
  outline: 2px solid var(--brand-solid-strong);
  outline-offset: 2px;
}
```

Now `Providers.tsx`, spreading the style config so the colour scales and `defaultTheme` reach `ThemeProvider`.

```tsx src/components/Providers.tsx
"use client";

import {
  DataThemeProvider,
  IconProvider,
  ThemeProvider,
  ToastProvider,
  type BorderStyle,
  type NeutralColor,
  type ScalingSize,
  type Schemes,
  type SolidStyle,
  type SolidType,
  type SurfaceStyle,
  type Theme,
  type TransitionStyle,
} from "@once-ui-system/core";
import type { ChartMode, ChartVariant } from "@once-ui-system/core/data";
// The Next adapters: links go through next/link and images through next/image.
import { LayoutProvider } from "@once-ui-system/core/next";
import { iconLibrary } from "../resources/icons";
import { dataStyle, style } from "../resources/once-ui.config";
import { OrgProvider } from "./OrgProvider";
import { UserProvider } from "./UserProvider";

export function Providers({ children }: { children: React.ReactNode }) {
  return (
    <LayoutProvider>
      <ThemeProvider
        theme={style.theme as Theme}
        defaultTheme={style.defaultTheme as Theme}
        brand={style.brand as Schemes | "custom"}
        accent={style.accent as Schemes | "custom"}
        neutral={style.neutral as NeutralColor | "custom"}
        brandScale={style.brandScale}
        accentScale={style.accentScale}
        neutralScale={style.neutralScale}
        solid={style.solid as SolidType}
        solidStyle={style.solidStyle as SolidStyle}
        border={style.border as BorderStyle}
        surface={style.surface as SurfaceStyle}
        transition={style.transition as TransitionStyle}
        scaling={style.scaling as ScalingSize}
      >
        <DataThemeProvider
          variant={dataStyle.variant as ChartVariant}
          mode={dataStyle.mode as ChartMode}
          height={dataStyle.height}
          axis={{
            stroke: dataStyle.axis.stroke,
          }}
          tick={{
            fill: dataStyle.tick.fill,
            fontSize: dataStyle.tick.fontSize,
            line: dataStyle.tick.line,
          }}
        >
          <ToastProvider>
            <IconProvider icons={iconLibrary}>
              <UserProvider>
                <OrgProvider>{children}</OrgProvider>
              </UserProvider>
            </IconProvider>
          </ToastProvider>
        </DataThemeProvider>
      </ThemeProvider>
    </LayoutProvider>
  );
}
```

Root layout: drop the Google fonts, and hand the full style config (scales, `defaultTheme`) to `ThemeInit` so the dark theme and brand colours paint on the server before first paint.

```tsx src/app/layout.tsx
import "@once-ui-system/core/css/styles.css";
import "@once-ui-system/core/css/tokens.css";
import "@/resources/custom.css";

import { LocaleProvider, Providers } from "@/components";
import { getLocale } from "@/lib/i18n/server";
import { baseURL, dataStyle, landing, style } from "@/resources";
import { Column, Flex, Meta, Schema, ThemeInit } from "@once-ui-system/core";

export async function generateMetadata() {
  return Meta.generate({
    title: landing.home.title,
    description: landing.home.description,
    baseURL: baseURL,
    image: landing.home.image,
  });
}

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const locale = await getLocale();

  return (
    <Flex
      suppressHydrationWarning
      data-scroll-behavior="smooth"
      as="html"
      lang={locale}
      fillWidth
    >
      <head>
        <Schema
          as="webPage"
          baseURL={baseURL}
          title={landing.home.title}
          description={landing.home.description}
          path={landing.home.path}
        />
        {/* Paints data-theme, the brand and neutral scales and the border
            style before first paint, so the dark default never flashes. */}
        <ThemeInit
          config={{
            theme: style.theme,
            defaultTheme: style.defaultTheme,
            neutral: style.neutral,
            brand: style.brand,
            accent: style.accent,
            brandScale: style.brandScale,
            accentScale: style.accentScale,
            neutralScale: style.neutralScale,
            solid: style.solid,
            solidStyle: style.solidStyle,
            border: style.border,
            surface: style.surface,
            transition: style.transition,
            scaling: style.scaling,
          }}
          dataStyle={{ mode: dataStyle.mode }}
        />
      </head>
      <LocaleProvider locale={locale}>
        <Providers>
          <Column as="body" background="page" fillWidth margin="0" padding="0" minHeight="100vh">
            <Column fillWidth horizontal="center" flex={1}>
              {children}
            </Column>
          </Column>
        </Providers>
      </LocaleProvider>
    </Flex>
  );
}
```

